// modules/mi-modulo-cpp/vector_math.hpp
#pragma once
#include <cmath>

namespace vector_math {
    struct Vec2 {
        double x, y;
        inline double length() const { return std::sqrt(x * x + y * y); }
        inline Vec2 normalized() const {
            double len = length();
            return len > 0 ? Vec2{x / len, y / len} : Vec2{0, 0};
        }
    };
